<div class="form-grid"><?php foreach(['namaPerusahaan'=>'Nama Perusahaan','emailPerusahaan'=>'Email Perusahaan','bidangUsaha'=>'Bidang Usaha','kontak'=>'Nomor Kontak','website'=>'Website'] as $k=>$label):?><label><?= e($label) ?><input type="<?= $k==='website'?'url':($k==='emailPerusahaan'?'email':'text') ?>" name="<?= e($k) ?>" value="<?= e(old($k,$profil[$k])) ?>" maxlength="<?= $k==='website'?250:($k==='kontak'?30:100) ?>"<?= in_array($k,['namaPerusahaan','emailPerusahaan'],true)?' required':'' ?>></label><?php endforeach;?></div>
