<aside class="stack"><section class="card"><h2>Status verifikasi</h2><?= badge($profil['statusVerifikasi']) ?><p class="muted"><?= e($profil['catatanVerifikasi']?:'Admin akan memeriksa legalitas perusahaan.') ?></p></section><section class="card"><h2>Legalitas Perusahaan</h2><?php foreach($legalitas as $d):?><div class="history-item"><a target="_blank" rel="noopener" href="<?= e(url('dokumen/lihat',['id'=>$d['idDokumen']])) ?>"><?= e($d['namaDokumen']) ?> ↗</a><p><?= badge($d['hasilPemeriksaan']) ?></p><small><?= e($d['catatan']) ?></small></div><?php endforeach;?>
